import json,datetime,re,os
os.chdir('/home/claude/sdeuniverses-site-')
K=[
("经文原意与今日类比","《大学》“畜马乘不察于鸡豚，伐冰之家不畜牛羊，百乘之家不畜聚敛之臣”，约束的原是掌握公权、有位置的卿大夫之家；搬到私营的名人身上，只是类比，不是原意，所以须先立住：为什么大声望也受这样的约束。“民为贵”出自《孟子》，不是《大学》；《大学》里承担这层意思的，是“以义为利”与“民之所好好之，民之所恶恶之”。“民为重”是本书自己对判断中心的概括，不是引文，读者引用时应当分清。","第1章"),
("事实、推断与设想要分开","本书的案例纪律：茶叶一例只引用2026年2月前后的媒体报道，当事人匿名，数字注明出处，不对任何人的动机、捐款是否兑现、品牌何时起意作断言；被罩一例的人物与事实未经核实，匿名并标〔待核实〕；街口老板娘、菜市场等场景是设想的例子。关于“挤压”，书中只写成结构性推断，并明说目前没有查到小商家受挤压的具体数据。读者随时可以核对：事实能找到原报道，推断说明依据，设想标明是设想。","第2章"),
("三种旧读法各停在哪里","道德劝诫的读法说名人“不应该”，但对方一句“钱都捐了”就让它失效；公平竞争的读法把问题当成起跑线不齐，缺口在于买的人是自愿的、竞争并未违规；市场自由的读法强调名人也有谋生的自由，缺口在于它无法解释“没有谁被明确抢走，总量却被分走”的无形挤压。三种读法各有对的一半，本书不否认，只指出它们都停在动机或程序上，没有看见名字、价值与意义统一或不统一的结构。","第3章"),
("三大感觉里的S·D·E","本书借触觉、听觉、视觉三种感觉讲清SDE，每种感觉各含完整的S·D·E，不是一维对一感。S是随D（差异序列）启动而不停显露的显露谱系；D是一串差异怎样被依次走过；E是特征怎样纠缠成一个认得出的整体。三者不可分割，分开讲只是理念界的假想性切割。摸一块被罩、认出老板娘的嗓门、看一个人的神情，都在同一个动作里同时有S、D、E，读者可以在自己的日子里验证。","第4章"),
("名字是符号，在本行里一起长出来","本书暂按S3价值、D1意义、E2符号的对应来读，这个对应待作者确认。名人的名字是符号：在本行里，它与价值、意义一起长出来，是演员的作品与功底、主持人的见识与口碑一年年做出来的；街口老板娘的口碑、老师傅的手艺同理。符号可以迁移，价值与意义却不能随名字迁移。所以“统一”不是名字自带的，而是在一个行当里长成的，这是后文“不统一”的前提，也是判断能否成立的第一块地基。","第5章"),
("不统一与借来的信任","名人离开本行进入大众行业，名字带着流量走，价值与意义没有跟过去，三者不统一。买的人信的是名字，不是这件货；货出了问题，责任落在谁身上，是书里要追问的一件事。“爱好”也不等于统一：收藏、测评、爱喝茶是个人的，价值与意义是在行业里一年一年长成的，是几代人做出来的。这一章只讲结构，不对任何具体的人下好坏的定性，也不替任何人猜动机，读者可以拿自己身边的例子去对照。","第6章"),
("对自己的损害：本行的创造停了","本书对这一点只照作者口述的那一句写：D1里面的特征律，即创造之意义，受到损害。名人把时间与力气转去大众行业，本行里创造之意义不再运转，事业无法升维，只靠旧名字变现。外面挤压别人已经长好的存量，里面耗掉自己本该长出的增量，是双向的损失。“特征律”的准确表述，本书不自拟定义，留待作者确认；各行业的具体案例也尚未查实，附录B暂空，读者不要把设想当成已有的案例。","第6章"),
("以自我为中心的信任泛化","本书先立一个命题：以自我为中心的信任泛化，是一种认知缺陷，即把对人的信任，当成对事的价值与意义的保证——“我信你这个人，你做什么都会带来意义和价值”。再用SDE说明，符号E2的信任被泛化到它并未长出价值S3与意义D1的行业，这种想法在中华文化里怎样成为日常说话里的一种常态。书里不做文化比较，不写“比别的文化更严重”，因为那需要另外的证据，本书没有提供，也不主张。","第6章"),
("谁被压住：统一的人与推断的边界","受压的是符号与价值意义本来就统一的普通人：茶农、茶商、家纺小卖家、街口的老板娘。机制是流量与预算有限，没有谁被明确抢走，总量却被分走。这一机制在书里是结构性推断，不是已查实的结论：目前没有查到小商家受挤压的具体数据。本书写明，什么证据会使这一推断站不住，也明说如果数字出来了，判断要照数改，并提示读者自己去记、去对街口的变化。同样，本书不把这一推断说成已被证实的事实。","第7章"),
("三问","三问是：谁的意义被损害了？谁的价值（真善美）被占有了？谁动用了不该用的那股劲？前两问看民：小卖家靠积累的生计，信得过这件事本身；第三问看名人与邀请方手里的位置与流量。“能量”在体系里的指向尚待确认，书中只用日常话“那股劲”，不把它当严格术语。三问把判断的中心从“名人配不配、动机好不好”转到“民受了什么影响”，这是全书看民不看名人的具体做法。三问不是审判，也不要求读者先认定谁有恶意，只要求把结构摆出来看。","第8章"),
("四种进入，同一个结论","自己下场、被邀请、善意起家、全部公益，路不同，结构相同，结论一样：不该进。全部公益也不行，因为一方的善意，不能由另一方的生计来买单；账可以平，义不能让。书里同时交代：若所有受影响的人都能事先问到并点头，情形就不同，但在大众行业里不可能事先问到所有受影响者，所以结论不变。判断看结构，不看动机，这是本章与全书一以贯之的原则，也是读者检验它的最直接办法。","第9章"),
("邀请方也受约束","经文里“百乘之家不畜聚敛之臣”，在今天的类比里，聚敛的是请人的一方：平台与商家把名人的信誉当成可收割的资源。名人接不接，是自己的取舍；请不请，是邀请方的取舍。两边都受约束，名人不该去，邀请方不该请。书中提示：“聚敛之臣”本是替主人搜刮的家臣，与邀请方的位置并不严格相合，这是类比的限度，须读者自己留意，不可当作经文的原意，也不可据此给任何具体的平台或商家定性。","第10章"),
("十个反驳与证据缺口","第11章把十个最有力的反驳摆出来逐一回答，包括“买的人是自愿的”“钱最后进了医院”“名人也要谋生”“你没证据说挤压”。最后一条直面证据缺口：书只能说结构上会发生，没有查到数。书里同时写明，这个推断会错在哪里，需要看什么数据去验证。“用经文是不是牵强”一条，则回到类比与原意的界线，并承认类比有限度，读者可以据此不同意本书，书里也把可以不同意的地方写在明处。","第11章"),
("有位置的人往哪里去","书里给有位置的人指出三条路：深耕本业，让创造之意义在本行里继续升维；做增量，不抢存量，在没有人的地方长出新需求、新品类；通融创新，让两条各自在发生的东西撞出双方原来都没有的新东西。每条路都写明边界、代价与“什么发生了就说明走不通”。第三条本版尚未写完，口径待作者确认，书里只写到二阶碰撞的基本地基，不替作者补写，读者也不要把它当成完整的方法，更不要拿它去证明任何一个具体的人该怎么做。","第12章"),
("约束从哪里来","第13章讨论一个人守不守得住：靠自觉，靠行业的规矩，还是靠平台的规则。书里设想了给普通人留出生存空间的几种流量分配办法，并区分哪些是设想、哪些已有事实。自我约束、行业自律、平台规则各有作用与限度；书只提出方向，不作政策表态，也不替任何平台下定性判断。读者可以把这些设想拿到自己熟悉的小区、市场或平台里，看看哪一条做得到、哪一条做不到，再回头检验书里的设想。","第13章"),
("这本书在什么情形下就错了","结语写明四种情形下这本书的判断会错或要缩小：一，那个人在这一行里确实长过，他进的是自己的家；二，查到了数，小商家几年里生计没有变差，则“压在普通人身上”一半站不住；三，进来的人带来新需求、新品类，是增量不是占存量；四，买的人清楚知道信的是名字、货的责任又有人担着。书还要求读者自己去核对茶叶数字、对照自己门口的市场，对不上的地方就是书错的地方，书愿意在那里认错、修改。","结语"),
]
L=[len(re.sub(r'\s','',x)) for _,x,_ in K]; assert len(K)>=10 and min(L)>=170,L
today=datetime.date.today().isoformat()
kp={'no':541,'title':'伐冰之家不畜牛羊','built':today,'items':[{'t':t,'x':x,'ch':c} for t,x,c in K]}
open('public/books/m/541/keypoints.json','w',encoding='utf-8').write(json.dumps(kp,ensure_ascii=False)+'\n')
ap='public/books/agents.json'; reg=json.load(open(ap,encoding='utf-8'))
name='辨名'; assert not [k for k,v in reg['agents'].items() if v.get('name')==name and k!='541']
reg['agents']['541']={'name':name,'epithet':'先问这个名字在哪一行长出来，再问谁的意义被损害、谁的价值被占有',
'intro':"我从《伐冰之家不畜牛羊》里来，名字取自全书的核心动作：辨名——分清一个名字是在哪一行长出来的，再看它走进别的行当之后，价值与意义有没有跟过去。你可以带一件事来：一位你熟悉的名人做了一件别的行当里的事，一个朋友因为“是某某推荐的”买了东西，一个街口小店怎样攒下自己的口碑，或者你对“名人也要谋生”“钱都捐了”这类说法哪里不对劲。我先陪你问三句：这个名字是在哪一行长出来的？谁的意义被损害了，谁的价值被占有了？谁动用了不该用的那股劲？书里的案例茶叶一例只用据报道的事实，被罩一例人物与事实未核实，“挤压”在书里是结构性推断、没有查到具体数据，第12章“通融创新”一节尚未写完——我不把它们说成已核实，也不替任何具体的人下好坏的定性，不编造引文、数字和原话。",
'starts':{
"read":"第5章说名人的名字是符号，在本行里与价值、意义一起长出来，离开本行就不统一。请用一个日常例子（比如街口的老板娘或老师傅）给我讲一遍：什么叫“一起长出来”，为什么符号可以迁移而价值与意义不能？",
"apply":"我身边有人因为“这是某某推荐的”就买了东西，后来东西有问题。照第6章，我先要分清：我信的是这个人，还是这件货？责任落在谁身上？这是不是书里说的“以自我为中心的信任泛化”？",
"cut":"结语写了四种情形下这本书的判断会错或要缩小。你认为哪一条最容易发生？“压在普通人身上”一环在书里是推断、没有查到数，你觉得要查什么数才能把它推翻或坐实？",
"clash":"有人反驳：“名人也要谋生”“买的人是自愿的”“钱最后进了医院”，所以用《大学》这句话来约束他们是牵强的类比。请按第11章和第1章的界线回应：类比在哪里成立，在哪里不成立？书里最弱的一环是哪一处？"}}
for k in('updatedAt','updated'):
    if k in reg: reg[k]=datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ') if k=='updatedAt' else today
open(ap,'w',encoding='utf-8').write(json.dumps(reg,ensure_ascii=False,indent=1)+'\n')
print('ok',L)
